pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // We cannot directly call initialize here because it requires real IERC20/IRewardRouterV2/IGlpManager deployments.
        // Instead, we will use vm.etch to mock the necessary interfaces and then call initialize.
        // Alternatively, we can deploy minimal mocks. Since forge fuzz gives us random addresses as parameters,
        // we can pass those as mock addresses. But we need to ensure the initialize call does not revert due to
        // sub-calls inside __GMXBatchingManager_init (which calls glpManager.vault()). We'll mock glpManager
        // with a simple contract that returns a vault address.
    }

    function testFuzz_property(address _sGlp, address _usdc, address _rewardRouter, address _glpManager, address _dnGmxJuniorVault, address _keeper) public {
        // Bound to exclude zero addresses where they would cause revert in initialize
        vm.assume(_sGlp != address(0));
        vm.assume(_usdc != address(0));
        vm.assume(_rewardRouter != address(0));
        vm.assume(_glpManager != address(0));
        vm.assume(_dnGmxJuniorVault != address(0));
        vm.assume(_keeper != address(0));

        // Deploy a minimal mock for glpManager that returns a non-zero vault address to avoid revert in __GMXBatchingManager_init
        MockGlpManager mockGlpManager = new MockGlpManager();
        vm.etch(_glpManager, address(mockGlpManager).code);

        // Deploy a minimal mock for rewardRouter to avoid potential sub-calls if any
        MockRewardRouter mockRewardRouter = new MockRewardRouter();
        vm.etch(_rewardRouter, address(mockRewardRouter).code);

        // Also need to mock IERC20 to return true on approvals/transfers if called in grantAllowances or elsewhere, but
        // initialize only sets storage, it doesn't call token functions. The only external call in __GMXBatchingManager_init
        // is glpManager.vault(), which we mocked. So we can call initialize safely.

        // Now call initialize
        c.initialize(
            IERC20(_sGlp),
            IERC20(_usdc),
            IRewardRouterV2(_rewardRouter),
            IGlpManager(_glpManager),
            _dnGmxJuniorVault,
            _keeper
        );

        // After successful initialization, the owner should be the deployer of c (this contract's setUp ran c = new C(),
        // so msg.sender during construction was this InvMutTest contract). However, ownership was transferred during
        // __Ownable_init() which runs _transferOwnership(_msgSender()), and that _msgSender() is the caller of initialize.
        // Since we are calling initialize from this test directly, the msg.sender is the InvMutTest contract itself.
        // So the expected owner is address(this).

        address expectedOwner = address(this);
        address actualOwner = c.owner();

        // Assert: the returned owner must equal the actual owner set during initialization.
        // The mutant returns address(0), which will break this assertion.
        assertEq(actualOwner, expectedOwner);
    }
}

